# Django — نمای تابعی
from django.http import JsonResponse
from .models import Book


def book_list(request):
    books = Book.objects.all()
    data = [
        {"id": b.id, "title": b.title, "price": str(b.price)}
        for b in books
    ]
    return JsonResponse(data, safe=False)


# Django — نمای کلاسی
from django.views import View


class BookDetailView(View):
    def get(self, request, pk):
        book = Book.objects.get(pk=pk)
        return JsonResponse({"id": book.id, "title": book.title})

# DRF — همان مفهوم با ابزار DRF
from rest_framework.views import APIView
from rest_framework.response import Response


class BookDetailView(APIView):
    def get(self, request, pk):
        book = Book.objects.get(pk=pk)
        return Response({"id": book.id, "title": book.title})

from django.contrib import admin
from .models import Author, Book


@admin.register(Author)
class AuthorAdmin(admin.ModelAdmin):
    list_display = ["full_name"]
    search_fields = ["full_name"]


@admin.register(Book)
class BookAdmin(admin.ModelAdmin):
    list_display = ["title", "author", "price", "is_active"]
    list_filter = ["is_active", "author"]
    search_fields = ["title", "isbn"]
    date_hierarchy = "published_at"
